-- 90_VERIFY.sql — 적용 후 확인 (SCM_MGR)
SET PAGESIZE 200 LINESIZE 300

SELECT 'PKG_NSCM_UI_EXCEL' OBJ, 'PACKAGE' TYP, STATUS, TO_CHAR(LAST_DDL_TIME,'YYYY-MM-DD HH24:MI:SS') LAST_DDL FROM USER_OBJECTS WHERE OBJECT_NAME='PKG_NSCM_UI_EXCEL' AND OBJECT_TYPE='PACKAGE';
SELECT 'PKG_NSCM_UI_EXCEL' OBJ, 'PACKAGE BODY' TYP, STATUS, TO_CHAR(LAST_DDL_TIME,'YYYY-MM-DD HH24:MI:SS') LAST_DDL FROM USER_OBJECTS WHERE OBJECT_NAME='PKG_NSCM_UI_EXCEL' AND OBJECT_TYPE='PACKAGE BODY';
SELECT 'PKG_DMF0074' OBJ, 'PACKAGE' TYP, STATUS, TO_CHAR(LAST_DDL_TIME,'YYYY-MM-DD HH24:MI:SS') LAST_DDL FROM USER_OBJECTS WHERE OBJECT_NAME='PKG_DMF0074' AND OBJECT_TYPE='PACKAGE';
SELECT 'PKG_DMF0074' OBJ, 'PACKAGE BODY' TYP, STATUS, TO_CHAR(LAST_DDL_TIME,'YYYY-MM-DD HH24:MI:SS') LAST_DDL FROM USER_OBJECTS WHERE OBJECT_NAME='PKG_DMF0074' AND OBJECT_TYPE='PACKAGE BODY';
SELECT NAME, TYPE, LINE, POSITION, TEXT FROM USER_ERRORS WHERE NAME IN ('PKG_NSCM_UI_EXCEL','PKG_DMF0074') ORDER BY NAME, TYPE, SEQUENCE;
SELECT OBJECT_NAME, OBJECT_TYPE FROM USER_OBJECTS WHERE STATUS='INVALID' ORDER BY 1;
SELECT PROGRAM_ID, SHEET_NAME, STORAGE_SQL_ID, CASE WHEN INSTR(HEADER_CONTENT,'Period(Fr)_Ni') > 0 THEN '2단 OK' ELSE 'CHECK' END HEADER_FORM FROM SCM_ADM_EXCEL_COLUMNS WHERE PROGRAM_ID IN ('DMF0074','DMF0074_40');
SELECT OWNER, SYNONYM_NAME FROM ALL_SYNONYMS WHERE OWNER='SCMP_APP' AND SYNONYM_NAME IN ('PKG_NSCM_UI_EXCEL','PKG_DMF0074');
SELECT GRANTEE, TABLE_NAME, PRIVILEGE FROM USER_TAB_PRIVS WHERE GRANTEE='SCMP_APP' AND TABLE_NAME IN ('PKG_NSCM_UI_EXCEL','PKG_DMF0074');
